package com.ebuddy.j2me;
import javax.microedition.lcdui.*;
public final class RegisterForm extends Form implements CommandListener { final EbuddyMidlet app; final TextField user=new TextField("User","",32,TextField.ANY); final TextField name=new TextField("Name","",40,TextField.ANY); final TextField pass=new TextField("Password","",32,TextField.PASSWORD); final Command create=new Command("Create",Command.OK,1); final Command back=new Command("Back",Command.BACK,2); public RegisterForm(EbuddyMidlet a){super("Register");app=a;append(user);append(name);append(pass);addCommand(create);addCommand(back);setCommandListener(this);} public void setBusy(boolean b){} public void fail(String s){setBusy(false);Alert x=new Alert("Register",s,null,AlertType.ERROR);x.setTimeout(2000);app.display.setCurrent(x,this);} public void commandAction(Command c,Displayable d){if(c==create)app.register(user.getString(),pass.getString(),name.getString());else app.showLogin();}}
